function wfValidateNode(n){if(!n||typeof n.id!=='string'||!['note','image','frame','table'].includes(n.type))throw Error('内容类型或编号无效');for(const k of ['x','y','w','h'])if(!Number.isFinite(n[k])||Math.abs(n[k])>=1000000)throw Error('位置或尺寸无效');if(n.w<=0||n.h<=0)throw Error('内容尺寸必须大于0');for(const k of ['title','body','userText','annotation','url'])if(n[k]!==undefined&&typeof n[k]!=='string')throw Error('文字字段格式错误');if(n.tags!==undefined&&(!Array.isArray(n.tags)||n.tags.some(t=>typeof t!=='string')))throw Error('标签格式错误');if(n.type==='table'&&(!Array.isArray(n.columns)||!n.columns.length||n.columns.length>100||n.columns.some(c=>typeof c!=='string')||!Array.isArray(n.rows)||n.rows.length>5000||n.rows.some(r=>!Array.isArray(r)||r.length!==n.columns.length||r.some(c=>typeof c!=='string'))))throw Error('表格行列不匹配')}
