 if(c.op==='add'){const value=clone(c.value);if(!value||typeof value.id!=='string'||value.id!==c.targetId||at>=0)throw Error('新增编号已存在或不匹配');if(entity==='asset'){if(value.mime!==bundleMime||value.path!=='')throw Error('新增库中内容必须是组合，不能借提案登记本地文件');if(!Array.isArray(value.bundle?.nodes)||!Array.isArray(value.bundle?.edges))throw Error('新增组合格式错误');wfValidateGraph(value.bundle);if(typeof value.title!=='string'||typeof value.folder!=='string')throw Error('组合名称或目录无效')}list.push(value);continue}
