function wfProposalSummaries(p,base){return p.changes.map((c,i)=>{const entity=p.resource==='library'?'asset':c.entity||'node',list=entity==='asset'?base.assets:entity==='edge'?base.edges:base.nodes,original=list.find(x=>x.id===c.targetId),title=original?.title||c.value?.title||c.targetId;let before=c.op==='add'?null:c.op==='delete'?c.before:c.before,after=c.op==='delete'?'删除这项内容':c.op==='add'?c.value:c.after;return {field:String(i),label:(c.op==='add'?'新增：':c.op==='delete'?'删除：':'修改：')+title+(c.reason?' · '+c.reason:''),before,after}})}
