window.addEventListener('paste',e=>{if(isTyping(e)||$('dialog').open)return;const text=e.clipboardData.getData('text/plain'),files=[...e.clipboardData.files];if(!text&&!files.length)return;e.preventDefault();e.stopImmediatePropagation();pastePayload(text,files,pasteAnchor(e.target)).catch(err=>toast(err.message))},true);

